#!/usr/bin/env python3
# luxarch:ledger hook v8 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Shared helpers for the commit-ledger hooks (record / stop-guard / clear)."""

from __future__ import annotations

import contextlib
import json
import os
import subprocess
import sys
import tempfile
import time
from collections.abc import Callable, Iterator
from pathlib import Path
from types import ModuleType

_FCNTL: ModuleType | None
try:
    import fcntl as _fcntl_module

    _FCNTL = _fcntl_module
except ImportError:  # not POSIX: the atomic replace still holds, the lock does not
    _FCNTL = None


def project_dir() -> Path:
    d = os.environ.get("CLAUDE_PROJECT_DIR")
    if d:
        return Path(d)
    try:
        return Path(
            subprocess.check_output(
                ["git", "rev-parse", "--show-toplevel"],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        )
    except Exception:
        return Path.cwd()


def tree_dir() -> Path:
    """The checkout the agent is working in: the top of the event's `cwd`, else the project dir.

    An agent works in its issue's worktree (`.claude/worktrees/<ISSUE-KEY>`, --doc
    FLEET-AGENT-CONDUCT-STANDARD, "Concurrent agents: one worktree per issue") while
    CLAUDE_PROJECT_DIR can still name the main checkout, so a `git rev-parse HEAD` run there
    recorded the main checkout's HEAD, not the commit just made."""
    cwd = str(_EVENT.get("cwd") or "")
    if cwd:
        try:
            top = subprocess.check_output(
                ["git", "-C", cwd, "rev-parse", "--show-toplevel"],
                text=True,
                stderr=subprocess.DEVNULL,
            ).strip()
        except Exception:
            top = ""
        if top:
            return Path(top)
    return project_dir()


def state_dir() -> Path:
    """Where session state lives: `.claude/` in the MAIN checkout, shared by every worktree.

    A worktree is removed when its issue lands, and the ledger must outlive it: the commits it
    recorded still have to be logged to LuxPM and pushed from the main checkout."""
    try:
        common = subprocess.check_output(
            [
                "git",
                "-C",
                str(tree_dir()),
                "rev-parse",
                "--path-format=absolute",
                "--git-common-dir",
            ],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        common = ""
    if common and Path(common).name == ".git":
        return Path(common).parent / ".claude"
    return project_dir() / ".claude"


def ledger_path() -> Path:
    return state_dir() / ".luxpm-ledger.json"


# ── Shared state, safe under concurrent sessions ────────────────────────────────────────────────
# Every session's hooks read, change and write the same files here. Each change is made under an
# exclusive lock on a sidecar `<file>.lock` (so two writers never drop each other's entry), and
# written to a temporary file in the same directory that replaces the real one in one step (so a
# reader never sees half a file). A file that exists but does not parse is kept aside as
# `<file>.unreadable-<time>` rather than overwritten, and a reader that must not guess (the Stop
# guard) is told it is unreadable instead of reading it as empty.


class Unreadable(ValueError):
    """A state file exists but cannot be read as the JSON it should hold."""


@contextlib.contextmanager
def _locked(path: Path) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(str(path) + ".lock", "a", encoding="utf-8") as fh:
        if _FCNTL is not None:
            _FCNTL.flock(fh.fileno(), _FCNTL.LOCK_EX)
        try:
            yield
        finally:
            if _FCNTL is not None:
                _FCNTL.flock(fh.fileno(), _FCNTL.LOCK_UN)


def _write_atomic(path: Path, text: str) -> None:
    fd, tmp = tempfile.mkstemp(
        dir=str(path.parent), prefix=f".{path.name}.", suffix=".tmp"
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(text)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp, path)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp)
        raise


def _read_json(path: Path, default: object) -> object:
    """The file's JSON, `default` when it does not exist; Unreadable when it exists and won't parse."""
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return default
    except OSError as exc:
        raise Unreadable(f"{path}: {exc}") from exc
    try:
        return json.loads(text)
    except _PAYLOAD_ERRORS as exc:
        raise Unreadable(f"{path}: {exc.__class__.__name__}") from exc


def _update_json(
    path: Path, default: object, change: Callable[[object], object]
) -> object:
    """Read, change and write `path` as one step no other session can interleave with."""
    with _locked(path):
        try:
            data = _read_json(path, default)
        except Unreadable:
            path.replace(path.with_name(f"{path.name}.unreadable-{int(time.time())}"))
            data = default
        new = change(data)
        _write_atomic(path, json.dumps(new, indent=2))
        return new


def _entries(data: object) -> list[dict[str, object]]:
    return [e for e in data if isinstance(e, dict)] if isinstance(data, list) else []


def read_ledger(strict: bool = False) -> list[dict[str, object]]:
    """The LuxPM ledger. With `strict`, a ledger that exists but cannot be read raises Unreadable
    (a Stop guard must not read it as empty); otherwise it reads as empty."""
    try:
        return _entries(_read_json(ledger_path(), []))
    except Unreadable:
        if strict:
            raise
        return []


def update_ledger(
    change: Callable[[list[dict[str, object]]], list[dict[str, object]]],
) -> list[dict[str, object]]:
    """Change the LuxPM ledger as one locked step: `change` gets the entries and returns the new ones."""
    return _entries(_update_json(ledger_path(), [], lambda d: change(_entries(d))))


def write_ledger(entries: list[dict[str, object]]) -> None:
    update_ledger(lambda _old: entries)


def git(*args: str) -> str:
    return git_at(tree_dir(), *args)


def git_at(where: Path, *args: str) -> str:
    """`git -C <where> <args>`'s output, or '' when it fails."""
    try:
        return subprocess.check_output(
            ["git", "-C", str(where), *args],
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        return ""


def event_cwd() -> Path:
    """The shell's directory for this event (where a `git -C <rel>` is relative to)."""
    cwd = str(read_event().get("cwd") or "")
    return Path(cwd) if cwd else tree_dir()


def session_id() -> str:
    """This agent session's id, from the hook payload if it was read, else the env.

    Claude Code puts `session_id` in every hook event. `read_event()` caches it so a hook that has
    already consumed stdin can still ask. Empty string when unavailable — entries written without a
    session are treated as everyone's, which keeps a pre-upgrade ledger from being ignored.
    """
    # str() at the boundary: the payload is untyped JSON, and an id is only ever compared
    # as a string.
    return str(_EVENT.get("session_id") or os.environ.get("CLAUDE_SESSION_ID", ""))


# A NAMED tuple, not an inline `except (OSError, ValueError)`. Under `target = "py314"` ruff
# formats the inline form to PEP 758's `except OSError, ValueError:`; under py311/py313 it keeps the
# parentheses. So the SAME emitted file has two canonical forms, and an emitted asset is supposed to
# be byte-identical everywhere — in a py314 repo `luxlint --format` rewrote it, `repo.hooks_current`
# then reported drift, and the two guards DEADLOCKED with no local fix.
#
# The fleet declares three targets today (4 guards py311, 7 repos py313, 14 repos py314), so an
# emitted asset must avoid every construct whose canonical formatting is target-dependent. A NAME has
# no parentheses for a formatter to take away.
_PAYLOAD_ERRORS = (OSError, ValueError, RecursionError)

_EVENT: dict[str, object] = {}


def read_event() -> dict[str, object]:
    """Parse the hook event from stdin ONCE and cache it (stdin can only be read once)."""
    global _EVENT
    if not _EVENT:
        try:
            data = json.load(sys.stdin)
        except _PAYLOAD_ERRORS:
            # Only a missing/malformed payload is tolerated. A bare `except Exception` here hid a
            # NameError (an unimported `sys`) as "no event", so record-commit silently recorded
            # NOTHING while exiting 0 — the same shape as the settings.json data loss.
            data = None
        # A payload that is JSON but not an object (a list, a number) is as unreadable as one
        # that is not JSON: every caller reads it with `.get`.
        _EVENT = data if isinstance(data, dict) else {}
    return _EVENT


def event_command() -> str:
    """The Bash command this event carries; '' when there is none or it is not text."""
    ti = read_event().get("tool_input")
    cmd = ti.get("command") if isinstance(ti, dict) else None
    return cmd if isinstance(cmd, str) else ""


def mine(entries: list[dict[str, object]]) -> list[dict[str, object]]:
    """The ledger entries belonging to THIS session.

    An entry with no session is included: it predates session stamping, so holding the current agent
    to it is the conservative choice. An entry stamped with a DIFFERENT session is another agent's
    work — it must not block this one, and this one must not log it (that would put wrong commits on
    someone else's ticket).
    """
    me = session_id()
    return [e for e in entries if not e.get("session") or e.get("session") == me]


def others(entries: list[dict[str, object]]) -> list[dict[str, object]]:
    me = session_id()
    return [e for e in entries if e.get("session") and e.get("session") != me]


# ── the LuxPM search marker ───────────────────────────────────────────────────────────────────────────
# A PostToolUse hook records "this session searched LuxPM" the moment a search RETURNS; the
# search-before-create hook reads it. Reading the transcript alone raced Claude Code's flush: the
# search that ran one call earlier was not in the file yet when the create was judged, so 4 of 11
# creates after a search were denied in one session.


def search_marker_path() -> Path:
    return state_dir() / ".luxpm-searched.json"


def _marker(data: object) -> dict[str, bool]:
    return {str(k): bool(v) for k, v in data.items()} if isinstance(data, dict) else {}


def _read_marker() -> dict[str, bool]:
    try:
        return _marker(_read_json(search_marker_path(), {}))
    except Unreadable:
        return {}


def mark_searched() -> None:
    sid = session_id()
    _update_json(search_marker_path(), {}, lambda d: {**_marker(d), sid: True})


def clear_searched() -> None:
    sid = session_id()
    _update_json(
        search_marker_path(),
        {},
        lambda d: {k: v for k, v in _marker(d).items() if k != sid},
    )


def has_searched() -> bool:
    return _read_marker().get(session_id(), False)


# ── what each session searched LuxPM FOR (v6) ─────────────────────────────────────────────────────────
# edit-history needs the terms, not just the fact: the first change to a file is allowed once this
# session has searched LuxPM for that file, because a hold on it lives in LuxPM, not in git.


def search_terms_path() -> Path:
    return state_dir() / ".luxpm-search-terms.json"


def _terms(data: object) -> dict[str, list[str]]:
    if not isinstance(data, dict):
        return {}
    return {
        str(k): [t for t in v if isinstance(t, str)]
        for k, v in data.items()
        if isinstance(v, list)
    }


def _read_terms(path: Path) -> dict[str, list[str]]:
    try:
        return _terms(_read_json(path, {}))
    except Unreadable:
        return {}


def _record_term(path: Path, term: str) -> bool:
    """Add `term` to this session's list in `path`. False when it cannot be written."""
    term, sid = term.strip(), session_id()
    if not term or not sid:
        return False

    def add(data: object) -> dict[str, list[str]]:
        terms = _terms(data)
        mine = terms.get(sid, [])
        terms[sid] = (mine if term in mine else [*mine, term])[-1000:]
        return terms

    try:
        _update_json(path, {}, add)
    except OSError:
        return False
    return True


def _writable(p: Path) -> bool:
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.exists():
            return p.is_file() and os.access(p, os.W_OK)
        return os.access(p.parent, os.W_OK)
    except OSError:
        return False


def record_search_term(term: str) -> bool:
    """Remember a LuxPM search term for this session. False when it cannot be written."""
    return _record_term(search_terms_path(), term)


def search_terms() -> list[str]:
    return _read_terms(search_terms_path()).get(session_id(), [])


def terms_writable() -> bool:
    """Can a search term be remembered here? A gate that waits for one must not wait forever."""
    return _writable(search_terms_path())


# ── which release writing guides each session has read in full ─────────────────────────────────────
# release-docs-read-guides: a change log or release notes file is written after its writing guides
# were read this session, so the guide is the template, not the previous release's file.


def guides_read_path() -> Path:
    return state_dir() / ".release-guides-read.json"


def record_guide_read(guide: str) -> bool:
    """Remember that this session read `guide` in full. False when it cannot be written."""
    return _record_term(guides_read_path(), guide)


def guides_read() -> list[str]:
    return _read_terms(guides_read_path()).get(session_id(), [])


def guides_writable() -> bool:
    return _writable(guides_read_path())


def commits_path() -> Path:
    """Every commit an agent session made here, by session, kept until it reaches upstream. Not
    the LuxPM ledger: that one is emptied once the work is logged, and the push guard still has to
    know whose commits are unpushed afterwards."""
    return state_dir() / ".session-commits.json"


def record_session_commit(sha: str, subject: str) -> None:
    entry: dict[str, object] = {"sha": sha, "subject": subject, "session": session_id()}

    def add(data: object) -> list[dict[str, object]]:
        entries = _entries(data)
        if any(e.get("sha") == sha for e in entries):
            return entries
        return [*entries, entry][-500:]

    _update_json(commits_path(), [], add)
